<?php require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/auth.php';require_login();$id=(int)($_GET['id']??0);$st=$pdo->prepare('SELECT * FROM import_batch WHERE id=?');$st->execute([$id]);$batch=$st->fetch();if(!$batch)die('Batch tidak ditemukan');if($_SERVER['REQUEST_METHOD']==='POST'){foreach($_POST['ep_id']??[] as $fid=>$epid){$fid=(int)$fid;$epid=(int)$epid;if($epid>0){$pdo->prepare('UPDATE import_file SET ep_id=?,status=\'dipetakan\',catatan=? WHERE id=? AND batch_id=?')->execute([$epid,$_POST['catatan'][$fid]??null,$fid,$id]);}else{$pdo->prepare('UPDATE import_file SET status=\'diabaikan\',catatan=? WHERE id=? AND batch_id=?')->execute([$_POST['catatan'][$fid]??null,$fid,$id]);}}$pdo->prepare('UPDATE import_batch SET status=\'dipetakan\' WHERE id=?')->execute([$id]);header('Location:mapping.php?id='.$id.'&saved=1');exit;}$eps=$pdo->query('SELECT id,kode,judul FROM elemen_penilaian ORDER BY urutan')->fetchAll();$st=$pdo->prepare('SELECT * FROM import_file WHERE batch_id=? ORDER BY relative_path');$st->execute([$id]);$files=$st->fetchAll();$page_title='Pemetaan Dokumen Lama';require __DIR__.'/../partials/header.php';?><div class="d-flex justify-content-between align-items-start"><div><h2>Pemetaan Dokumen Lama</h2><p><?=htmlspecialchars($batch['nama_batch'])?> · Tahun <?=$batch['tahun_sumber']?> · <?=$batch['total_file']?> file</p></div><div class="d-flex gap-2"><a class="btn btn-outline-success" href="download-zip.php?id=<?=$batch['id']?>">⬇ Download ZIP</a><span class="badge text-bg-warning align-self-start">Review wajib</span></div></div><?php if(isset($_GET['saved'])):?><div class="alert alert-success">Pemetaan tersimpan.</div><?php endif;?><div class="alert alert-warning">File ZIP baru didaftarkan sebagai arsip. Pilih EP untuk file yang relevan. Sistem tidak otomatis menganggap dokumen lama masih berlaku.</div><form method="post"><div class="card shadow-sm border-0"><div class="card-body table-responsive"><table class="table align-middle"><thead><tr><th>File</th><th>Ukuran</th><th>EP MRMIK</th><th>Catatan Review</th><th>Download</th><th>Aksi</th></tr></thead><tbody><?php foreach($files as $f):?><tr><td><?=htmlspecialchars($f['relative_path'])?></td><td><?=number_format($f['size_bytes']/1024,1)?> KB</td><td><select class="form-select" name="ep_id[<?=$f['id']?>]"><option value="0">— Abaikan / arsip umum —</option><?php foreach($eps as $e):?><option value="<?=$e['id']?>" <?=($f['ep_id']==$e['id']?'selected':'')?>><?=htmlspecialchars($e['kode'].' — '.$e['judul'])?></option><?php endforeach;?></select></td><td><input class="form-control" name="catatan[<?=$f['id']?>]" value="<?=htmlspecialchars($f['catatan']??'')?>" placeholder="Masih berlaku / perlu revisi / arsip"></td><td><a class="btn btn-sm btn-outline-success" href="download.php?id=<?=$f['id']?>">⬇ Download</a></td><td><a class="btn btn-sm btn-outline-primary" href="review.php?id=<?=$f['id']?>">Review / Aktifkan</a></td></tr><?php endforeach;?></tbody></table></div></div><button class="btn btn-success mt-3">Simpan Pemetaan</button></form><?php require __DIR__.'/../partials/footer.php';